SOURCE="def closedIsland(grid):\n    rows, cols = len(grid), len(grid[0])\n\n    # 检查岛屿是否封闭的DFS函数\n    def dfs(r, c):\n        if grid[r][c] == 1:\n            return True\n        if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:\n            return False\n        \n        # 标记当前单元格为已访问\n        grid[r][c] = 1\n        \n        # 检查所有方向\n        up = dfs(r - 1, c)\n        down = dfs(r + 1, c)\n        left = dfs(r, c - 1)\n        right = dfs(r, c + 1)\n        \n        return up and down and left and right\n\n    closed_islands = 0\n    for r in range(1, rows - 1):  # 从1开始，忽略边界\n        for c in range(1, cols - 1):  # 从1开始，忽略边界\n            if grid[r][c] == 0 and dfs(r, c):\n                closed_islands += 1\n\n    return closed_islands\n\n# 读取输入\ngrid = []\nfor _ in range(10):\n    row = list(map(int, input().split(',')))\n    grid.append(row)\n\n# 输出结果\nprint(closedIsland(grid))\n\n"
with tempfile.NamedTemporaryFile('w',suffix='.py') as f:
 f.write(SOURCE); f.flush()
 root=Path(__file__).parent/'data'
 for i,c in enumerate(CASES):
  o=subprocess.run(['python3',f.name],input=c,text=True,capture_output=True,check=True).stdout
  (root/f'{i}.in').write_text(c); (root/f'{i}.out').write_text(o)
